// Observation only. No source, SQL, creator, cleanup or record authority enters
// ordinary main through this channel; normal bootstrap independently does all of it.
pub(crate) const SERVICE_OBSERVATION_CHANNEL:&str="STARLANE_PRIVATE_SERVICE_OBSERVATION_CHANNEL";
#[derive(serde::Serialize,serde::Deserialize)]#[serde(deny_unknown_fields)]
struct ServiceObservationHello{purpose:String,version:u32,nonce:String,child_elf_stamp:String,child_elf_sha256:String,parent_elf_stamp:String,parent_elf_sha256:String}
#[derive(serde::Serialize,serde::Deserialize)]#[serde(deny_unknown_fields)]
struct ServiceObservationReady{purpose:String,version:u32,nonce:String,listener_identity:Identity,address:std::net::SocketAddr}
pub(crate) struct ServiceObservationChild{channel:File,wire:ServiceObservationHello,parent:libc::ucred,parent_elf:File,child_elf:File}
impl ServiceObservationChild{
 pub(crate) fn receive_if_configured()->anyhow::Result<Option<Self>>{
  let raw=match std::env::var(SERVICE_OBSERVATION_CHANNEL){Ok(value)=>value,Err(std::env::VarError::NotPresent)=>return Ok(None),Err(_)=>anyhow::bail!("Service observation locator invalid")};anyhow::ensure!(std::env::args_os().len()==1,"Service observation is zero-argument ordinary main only");let fd:i32=raw.parse()?;anyhow::ensure!(fd>=3&&fd.to_string()==raw,"Service observation descriptor locator malformed");Ok(Some(Self::receive_fd(fd)?))
 }
 fn receive_fd(fd:i32)->anyhow::Result<Self>{use std::os::fd::FromRawFd;let copy=unsafe{libc::fcntl(fd,libc::F_DUPFD_CLOEXEC,3)};anyhow::ensure!(copy>=0,"Service observation channel absent");let channel=unsafe{File::from_raw_fd(copy)};
  let mut peer:libc::ucred=unsafe{std::mem::zeroed()};let mut length=std::mem::size_of_val(&peer)as libc::socklen_t;anyhow::ensure!(unsafe{libc::getsockopt(channel.as_raw_fd(),libc::SOL_SOCKET,libc::SO_PEERCRED,(&mut peer as *mut libc::ucred).cast(),&mut length)}==0&&length as usize==std::mem::size_of_val(&peer)&&peer.pid==unsafe{libc::getppid()}&&peer.uid==unsafe{libc::geteuid()}&&peer.gid==unsafe{libc::getegid()},"Service observation is not original kernel parent");
  let packet=verification_worker_receive(&channel)?;anyhow::ensure!(packet.files.is_empty()&&packet.credentials.pid==peer.pid&&packet.credentials.uid==peer.uid&&packet.credentials.gid==peer.gid,"Service observation hello carried authority or foreign sender");let wire:ServiceObservationHello=serde_json::from_slice(&packet.bytes)?;anyhow::ensure!(wire.purpose=="starlane-ordinary-service-observation"&&wire.version==1&&uuid::Uuid::parse_str(&wire.nonce)?.to_string()==wire.nonce,"Service observation purpose/nonce invalid");
  let parent_elf=File::open(format!("/proc/{}/exe",peer.pid))?;let child_elf=File::open("/proc/self/exe")?;anyhow::ensure!(verification_worker_stamp(&parent_elf)?==wire.parent_elf_stamp&&hash_file(&parent_elf,parent_elf.metadata()?.len())?==wire.parent_elf_sha256&&verification_worker_stamp(&child_elf)?==wire.child_elf_stamp&&hash_file(&child_elf,child_elf.metadata()?.len())?==wire.child_elf_sha256,"Service observation selected parent/child ELF differs");let value=Self{channel,wire,parent:peer,parent_elf,child_elf};value.fence()?;Ok(value)
 }
 fn fence(&self)->anyhow::Result<()>{anyhow::ensure!(unsafe{libc::getppid()}==self.parent.pid&&self.parent.uid==unsafe{libc::geteuid()}&&self.parent.gid==unsafe{libc::getegid()},"Original observing parent retired");anyhow::ensure!(verification_worker_stamp(&self.parent_elf)?==self.wire.parent_elf_stamp&&verification_worker_stamp(&File::open(format!("/proc/{}/exe",self.parent.pid))?)?==self.wire.parent_elf_stamp&&verification_worker_stamp(&self.child_elf)?==self.wire.child_elf_stamp&&verification_worker_stamp(&File::open("/proc/self/exe")?)?==self.wire.child_elf_stamp,"Original service observation ELF changed");Ok(())}
 pub(crate) fn ready(self,listener:&tokio::net::TcpListener)->anyhow::Result<ServiceObservationLifetime>{use std::os::fd::FromRawFd;self.fence()?;let copy=unsafe{libc::fcntl(listener.as_raw_fd(),libc::F_DUPFD_CLOEXEC,3)};anyhow::ensure!(copy>=0,"Actual service listener cannot be retained");let selected=unsafe{File::from_raw_fd(copy)};let address=ordinary_listener_address(&selected)?;let ready=ServiceObservationReady{purpose:"starlane-ordinary-service-observation-ready".into(),version:1,nonce:self.wire.nonce.clone(),listener_identity:identity(&selected)?,address};ordinary_listener_send(&self.channel,&serde_json::to_vec(&ready)?,&[&selected])?;self.fence()?;Ok(ServiceObservationLifetime(self))}
}
pub(crate) struct ServiceObservationLifetime(ServiceObservationChild);
impl ServiceObservationLifetime{pub(crate) async fn parent_retired(self){loop{if self.0.fence().is_err(){return;}let mut poll=libc::pollfd{fd:self.0.channel.as_raw_fd(),events:libc::POLLIN|libc::POLLHUP|libc::POLLERR,revents:0};let status=unsafe{libc::poll(&mut poll,1,0)};if status<0||poll.revents!=0{return;}tokio::time::sleep(std::time::Duration::from_millis(250)).await;}}}
#[cfg(test)]struct ServiceObservationParent{wire:ServiceObservationHello,executable:File,listener:Option<File>,queued:bool,received:bool}
#[cfg(test)]impl ServiceObservationParent{
 fn prepare(executable:File)->anyhow::Result<Self>{let parent=File::open("/proc/self/exe")?;let wire=ServiceObservationHello{purpose:"starlane-ordinary-service-observation".into(),version:1,nonce:uuid::Uuid::new_v4().to_string(),child_elf_stamp:verification_worker_stamp(&executable)?,child_elf_sha256:hash_file(&executable,executable.metadata()?.len())?,parent_elf_stamp:verification_worker_stamp(&parent)?,parent_elf_sha256:hash_file(&parent,parent.metadata()?.len())?};Ok(Self{wire,executable,listener:None,queued:false,received:false})}
 fn queue_once(&mut self,channel:&File)->anyhow::Result<()>{anyhow::ensure!(!self.queued,"Service observation consumed");self.queued=true;ordinary_listener_send(channel,&serde_json::to_vec(&self.wire)?,&[])?;Ok(())}
 fn receive_once(&mut self,channel:&File,child:&mut std::process::Child)->anyhow::Result<std::net::SocketAddr>{anyhow::ensure!(self.queued&&!self.received&&child.try_wait()?.is_none(),"Service observation selected child absent/consumed");self.received=true;let packet=verification_worker_receive(channel)?;anyhow::ensure!(packet.credentials.pid==i32::try_from(child.id())?&&packet.credentials.uid==unsafe{libc::geteuid()}&&packet.credentials.gid==unsafe{libc::getegid()}&&packet.files.len()==1,"Service observation ready foreign sender/FD count");let ready:ServiceObservationReady=serde_json::from_slice(&packet.bytes)?;anyhow::ensure!(ready.purpose=="starlane-ordinary-service-observation-ready"&&ready.version==1&&ready.nonce==self.wire.nonce,"Service observation ready purpose/nonce differs");let file=packet.files.into_iter().next().unwrap();anyhow::ensure!(identity(&file)?==ready.listener_identity&&ordinary_listener_address(&file)?==ready.address,"Actual returned service listener identity/address differs");let actual=File::open(format!("/proc/{}/exe",child.id()))?;anyhow::ensure!(verification_worker_stamp(&actual)?==self.wire.child_elf_stamp&&hash_file(&actual,actual.metadata()?.len())?==self.wire.child_elf_sha256&&verification_worker_stamp(&self.executable)?==self.wire.child_elf_stamp,"Observed service is not selected normal ELF");anyhow::ensure!(child.try_wait()?.is_none(),"Observed service exited during actual admission");self.listener=Some(file);Ok(ready.address)}
 fn fence(&self)->anyhow::Result<()>{let file=self.listener.as_ref().context("Original observed service listener not retained")?;ordinary_listener_address(file)?;anyhow::ensure!(verification_worker_stamp(&self.executable)?==self.wire.child_elf_stamp,"Original expected service ELF changed");Ok(())}
}
#[cfg(test)]mod service_observation_controls{
 use super::*;use std::os::unix::process::CommandExt;
 const CHILD:&str="storage::restoration::linux::service_observation_controls::service_observation_kernel_child";
 #[tokio::test]#[ignore="actual observation-only SCM child; no normal bootstrap/source/record authority"]
 async fn service_observation_kernel_child()->anyhow::Result<()>{
  let fd:i32=std::env::var("SERVICE_OBSERVATION_TEST_FD")?.parse()?;
  let observer=ServiceObservationChild::receive_fd(fd)?;
  let listener=tokio::net::TcpListener::bind("127.0.0.1:0").await?;
  let lifetime=observer.ready(&listener)?;
  if std::env::var_os("SERVICE_OBSERVATION_TEST_RETIRE").is_some(){tokio::time::timeout(std::time::Duration::from_secs(15),lifetime.parent_retired()).await?;return Ok(());}
  use tokio::io::{AsyncReadExt,AsyncWriteExt};let(mut socket,_)=tokio::time::timeout(std::time::Duration::from_secs(15),listener.accept()).await??;socket.write_all(b"OBSERVATION ONLY").await?;let mut done=[0;1];anyhow::ensure!(tokio::time::timeout(std::time::Duration::from_secs(15),socket.read(&mut done)).await??==0,"Unexpected child probe");drop(lifetime);Ok(())
 }
 fn spawn(channel:&File,retire:bool)->anyhow::Result<std::process::Child>{let fd=channel.as_raw_fd();let mut command=std::process::Command::new("/proc/self/exe");command.args(["--exact",CHILD,"--ignored","--nocapture","--test-threads=1"]).env("SERVICE_OBSERVATION_TEST_FD",fd.to_string()).stdin(std::process::Stdio::null()).stdout(std::process::Stdio::null()).stderr(std::process::Stdio::null());if retire{command.env("SERVICE_OBSERVATION_TEST_RETIRE","1");}unsafe{command.pre_exec(move||{let flags=libc::fcntl(fd,libc::F_GETFD);if flags<0||libc::fcntl(fd,libc::F_SETFD,flags&!libc::FD_CLOEXEC)<0{return Err(io::Error::last_os_error());}Ok(())});}Ok(command.spawn()?)}
 fn readable(channel:&File,child:&mut std::process::Child)->anyhow::Result<()>{let until=std::time::Instant::now()+std::time::Duration::from_secs(15);loop{anyhow::ensure!(child.try_wait()?.is_none(),"Observation child exited before readiness");let mut poll=libc::pollfd{fd:channel.as_raw_fd(),events:libc::POLLIN,revents:0};anyhow::ensure!(unsafe{libc::poll(&mut poll,1,50)}>=0,"Readiness poll failed");if poll.revents!=0{return Ok(());}anyhow::ensure!(std::time::Instant::now()<until,"Observation child silence exceeded15s");}}
 #[test]fn observation_actual_child_and_retained_port()->anyhow::Result<()>{use std::io::Read;let mut owner=ServiceObservationParent::prepare(File::open("/proc/self/exe")?)?;let(a,b)=verification_worker_pair()?;owner.queue_once(&a)?;let mut child=spawn(&b,false)?;drop(b);let result=(||->anyhow::Result<()>{readable(&a,&mut child)?;let address=owner.receive_once(&a,&mut child)?;owner.fence()?;anyhow::ensure!(owner.receive_once(&a,&mut child).is_err()&&owner.queue_once(&a).is_err(),"Consumed readiness replayed");let mut socket=std::net::TcpStream::connect(address)?;socket.set_read_timeout(Some(std::time::Duration::from_secs(15)))?;let mut bytes=[0;b"OBSERVATION ONLY".len()];socket.read_exact(&mut bytes)?;anyhow::ensure!(&bytes==b"OBSERVATION ONLY","Actual kernel child bytes differ");drop(socket);anyhow::ensure!(child.wait()?.success(),"Actual kernel child failed");anyhow::ensure!(std::net::TcpListener::bind(address).is_err(),"Released child port rebound despite held listener");drop(owner);drop(std::net::TcpListener::bind(address)?);Ok(())})();let _=child.kill();let _=child.wait();result}
 #[test]fn observation_purpose_elf_and_authority_fds_refuse()->anyhow::Result<()>{for case in 0..3{let owner=ServiceObservationParent::prepare(File::open("/proc/self/exe")?)?;let mut value=serde_json::to_value(&owner.wire)?;if case==0{value["purpose"]="starlane-ordinary-listener".into();}if case==1{value["child_elf_sha256"]="0".repeat(64).into();}let(a,b)=verification_worker_pair()?;let null=File::open("/dev/null")?;let files=if case==2{vec![&null]}else{vec![]};ordinary_listener_send(&a,&serde_json::to_vec(&value)?,&files)?;let mut child=spawn(&b,false)?;drop(b);anyhow::ensure!(!child.wait()?.success(),"Foreign purpose/ELF/authority FD admitted");}Ok(())}
 #[test]fn observation_wrong_nonce_consumes_and_channel_retirement_stops_child()->anyhow::Result<()>{let mut owner=ServiceObservationParent::prepare(File::open("/proc/self/exe")?)?;let(a,b)=verification_worker_pair()?;owner.queue_once(&a)?;owner.wire.nonce=uuid::Uuid::new_v4().to_string();let mut child=spawn(&b,true)?;drop(b);let result=(||->anyhow::Result<()>{readable(&a,&mut child)?;anyhow::ensure!(owner.receive_once(&a,&mut child).is_err(),"Foreign nonce admitted");anyhow::ensure!(owner.receive_once(&a,&mut child).is_err(),"Rejected attempt replayed");drop(a);let until=std::time::Instant::now()+std::time::Duration::from_secs(3);loop{if let Some(status)=child.try_wait()?{anyhow::ensure!(status.success(),"Channel retirement child failed");break;}anyhow::ensure!(std::time::Instant::now()<until,"Child ignored original channel retirement");std::thread::sleep(std::time::Duration::from_millis(20));}Ok(())})();let _=child.kill();let _=child.wait();result}
 #[test]fn observation_failed_spawn_and_full_queue_consume()->anyhow::Result<()>{let mut owner=ServiceObservationParent::prepare(File::open("/proc/self/exe")?)?;let(a,_b)=verification_worker_pair()?;let payload=[7;16384];let mut count=0;while ordinary_listener_send(&a,&payload,&[]).is_ok(){count+=1;anyhow::ensure!(count<4096,"Kernel queue unbounded");}let began=std::time::Instant::now();anyhow::ensure!(owner.queue_once(&a).is_err()&&owner.queue_once(&a).is_err()&&began.elapsed()<std::time::Duration::from_secs(3),"Full queue did not consume promptly");let mut owner=ServiceObservationParent::prepare(File::open("/proc/self/exe")?)?;let(a,_b)=verification_worker_pair()?;owner.queue_once(&a)?;anyhow::ensure!(std::process::Command::new("/definitely-absent-owned-service-observation").spawn().is_err()&&owner.queue_once(&a).is_err(),"Failed spawn attempt reused");Ok(())}
}
